package cli

import (
	"github.com/spf13/cobra"
)

func newHotelsCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:         "hotels",
		Short:       "Search real hotel availability and rates",
		Annotations: map[string]string{"mcp:read-only": "true", "pp:parent-group": "true", "pp:api-resource": "true"},
		RunE:        parentNoSubcommandRunE(flags),
	}

	cmd.AddCommand(newHotelsSearchCmd(flags))
	return cmd
}
